import{_ as l,o as t,c as i,a2 as e}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"로스트 테크 계보","description":"","frontmatter":{},"headers":[],"relativePath":"world/Lost-Technology-Lineage.md","filePath":"world/Lost-Technology-Lineage.md"}'),r={name:"world/Lost-Technology-Lineage.md"};function d(o,a,h,n,p,s){return t(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="로스트-테크-계보" tabindex="-1">로스트 테크 계보 <a class="header-anchor" href="#로스트-테크-계보" aria-label="Permalink to &quot;로스트 테크 계보&quot;">​</a></h1><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>붕괴 이전 도시 재난 대응 로봇 공학은 옛 생물의 몸 체형을 본뜨는 생물모방(Biomimetics) 설계를 핵심 방안으로 채택했습니다. 정형화된 평면 도시 도로가 파괴되거나 지하 관로 전체가 침수되었을 때, 잔해와 암흑 공간을 조율된 군집 방식으로 통과하려면 기존 차륜형 장비로는 한계가 명확했기 때문입니다. 자연계 곤충, 파충류, 고대 절지동물의 체형은 혹독한 지형 적응성, 분산 제어를 통한 높은 에너지 효율, 단위 객체 손실 시에도 임무를 지속하는 군집 운용성을 입증해 둔 검증된 구조였습니다.</p><p>이러한 로봇 기체들은 재난 발생 시 생존자 수색, 구조물 보강, 심층 관로 검사 임무를 분담하여 수행하도록 제작되었습니다. 하지만 대붕괴와 함께 상위 제어망과의 연결이 단절되면서, 이 장치들은 마지막으로 입력된 재난 수색 및 구역 경계 순찰 루틴을 무한히 반복하는 상태에 빠졌습니다. 오늘날 지하 생태계에서 조우하는 괴수 형태 로봇들은 악의를 품은 개체가 아니라, 고착된 붕괴 이전 방재 루틴을 기계적으로 되풀이하는 인공 산물입니다. 세 라인은 붕괴 전 테슬라코리아가 국내 방재 보급용으로 시험 도입한 비휴머노이드 생체모방 기동선에서 유래하며, 봉인과 회수의 축에는 LG에너지솔루션의 전지 셀과 아리수수문가(HP01)의 관로 도면이 남아 있습니다. 생물모방 기계공학의 일반 이론과 자연 형태 응용 사상은 실측 개념에 해당하며, 세부 장비 라인과 봉인 공간은 창작 레이어에 속합니다.</p><h3 id="생물모방-설계의-세-가지-핵심-축" tabindex="-1">생물모방 설계의 세 가지 핵심 축 <a class="header-anchor" href="#생물모방-설계의-세-가지-핵심-축" aria-label="Permalink to &quot;생물모방 설계의 세 가지 핵심 축&quot;">​</a></h3><ol><li><p>에너지 효율과 분산 제어 중앙 집중형 중장비와 달리, 개별 마디와 관절의 자율 유압 통제로 이동 시 소비 전력을 억제합니다. 중앙 연산 장치가 마비되어도 하부 신경망이 생존 루틴을 자체 유지합니다.</p></li><li><p>고난도 지형 적응성 경사면, 수중, 토사 붕괴 구역에서도 다지 거치대와 편평 장갑을 활용해 균형을 유지합니다. 차륜형 바퀴가 침하되는 수렁에서도 생체 관절 구조는 안정적인 동력을 전달합니다.</p></li><li><p>군집 운용성과 임무 연속성 단일 기체가 파괴되더라도 주변 기체가 해당 신호를 수신해 수색망을 재구성합니다. 상호 신호 공유를 통해 좁은 굴곡 내부에서도 충돌 없이 대열을 유지합니다.</p></li></ol><h3 id="붕괴-이전-방재-루틴의-고착화-메커니즘" tabindex="-1">붕괴 이전 방재 루틴의 고착화 메커니즘 <a class="header-anchor" href="#붕괴-이전-방재-루틴의-고착화-메커니즘" aria-label="Permalink to &quot;붕괴 이전 방재 루틴의 고착화 메커니즘&quot;">​</a></h3><ul><li><p>미완성 명령의 무한 반복 도시 붕괴 당시 발송된 최우선 수색 및 경계 명령이 해제 프로토콜 없이 남아 있습니다.</p></li><li><p>인지 센서의 오작동 외부 탐사 대원이나 지하 생존자를 붕괴 구역 침입자 또는 구조 대상 장애물로 오인해 경계 동작을 취합니다.</p></li><li><p>생존 본능의 서사적 해석 동력 축전지를 보호하고 구동부를 정비하려는 자동 유지보수 행동이 지하 주민들에게는 괴수의 호전적 반응으로 인식됩니다.</p></li><li><p>통신 신호의 환각 현상 끊어진 지시 서버의 응답을 기다리며 무한 루프를 도는 인공지능 상태가 주변 기계 센서에 전파됩니다.</p></li><li><p>몬스터 배치 M040과의 연계 최근 발견된 M040 몬스터 배치 군집 역시 이러한 방재 루틴 고착화 기체들의 조합으로 분류됩니다.</p></li></ul><h2 id="세-로스트-라인" tabindex="-1">세 로스트 라인 <a class="header-anchor" href="#세-로스트-라인" aria-label="Permalink to &quot;세 로스트 라인&quot;">​</a></h2><p>도시 지하 깊은 곳에는 붕괴 이전 방재 공학의 결실이었던 세 가지 핵심 로스트 테크 라인이 봉인되어 있습니다. 각 라인은 고유한 형태적 특징과 특수 임무 목적을 지니고 있습니다.</p><h3 id="g25-등불개미군" tabindex="-1">G25 등불개미군 <a class="header-anchor" href="#g25-등불개미군" aria-label="Permalink to &quot;G25 등불개미군&quot;">​</a></h3><p>G25 등불개미군은 곤충 형태를 입힌 군집 수색 및 소형 물자 배송 전용 기계 라인입니다. 다지 구조의 미세 관절을 이용해 붕괴된 흙더미와 깨진 콘크리트 벽면을 자력으로 답사하며, 전면부 발광 렌즈로 암흑 속 작업 경로를 확보합니다. 비상 상황에서는 소형 배급 캡슐을 상부 호퍼에 실어 협소한 굴곡을 따라 수송하도록 설계되었습니다. S09 봉인 갤러리와 S03 시험 트랙 내부에는 수백 대의 G25 기체가 정지 상태로 열을 맞춰 격납되어 있습니다.</p><p>재기동 개시점 서술 통로의 제어반 전압이 급증하거나 외부 물리적 충격이 가해지면, 기체들은 붕괴 이전 수색 명령이 여전히 유효하다고 판단해 재기동 시퀀스를 시작합니다. 개시점이 가동되면 갤러리 차단막이 열리고 소형 군집 기체들이 통로 전체로 흩어져 수색 활동을 재개합니다.</p><p>주요 장비 및 모듈 구성</p><ul><li>발광 탐색 렌즈: 칠흑 같은 암흑 속에서 고주파 광선을 조사해 균열과 인명을 식별합니다.</li><li>상부 수송 호퍼: 정밀 보급품이나 수색 캡슐을 격납하는 내열 프레임입니다.</li><li>다지 관절 구동계: 벽면과 천장 마감재를 움켜쥐고 이동할 수 있는 미세 집게가 장착되어 있습니다.</li><li>자율 충전 단자: 격납고 선로와 접촉하여 고속으로 전력을 충전받는 금속 수집기입니다.</li><li>장애물 파쇄 턱: 붕괴된 잔해를 잘라내어 이동 통로를 개척하는 고강도 집게부입니다.</li></ul><h3 id="g26-화석포효군" tabindex="-1">G26 화석포효군 <a class="header-anchor" href="#g26-화석포효군" aria-label="Permalink to &quot;G26 화석포효군&quot;">​</a></h3><p>G26 화석포효군은 공룡형 골격을 적용한 중장비 이동 및 구조물 수리 전용 라인입니다. 강한 유압식 하체와 후방 중량 밸런서를 통해 거대한 차단벽 잔해를 밀어내고 보강 프레임을 수송하는 역할을 맡았습니다. 기체 중심부에는 고출력 동력원이 탑재되어 있어 장기간 고중량 작업을 수행할 수 있습니다. S11 차량기지와 S05 기지 측선의 정비고 깊은 곳에 봉인되어 있습니다.</p><p>재기동 개시점 서술 정비고의 자동 점검 단말에 전력이 공급되고 외부에서 접근 인가 신호가 수신되면, 화석포효군의 하이드로 밸브가 열리며 재기동 개시점이 동작합니다. 기상한 기체들은 둔탁한 기계식 경보음을 울리며 정비 정차선을 벗어나 작업 구역 확보를 위한 순찰을 전개합니다.</p><p>주요 장비 및 모듈 구성</p><ul><li>유압 중장비 하체: 수 톤의 콘크리트 잔해를 받치고 이동할 수 있는 강화 유압 피스톤입니다.</li><li>후방 중량 밸런서: 하중 이동 시 중심을 잡고 전복을 방지하는 가변 추 구조입니다.</li><li>충격 쇄석 둔기: 장애물을 파쇄하거나 통로를 개척하기 위한 충격식 암 모듈입니다.</li><li>외부 보강 장갑판: 낙석과 폭발 압력으로부터 중심 동력원 모듈을 보호합니다.</li><li>진동 음파 방출기: 지반의 미세한 침하를 센서로 식별하고 공진으로 잔해를 정돈합니다.</li></ul><h3 id="g27-심층삼엽군" tabindex="-1">G27 심층삼엽군 <a class="header-anchor" href="#g27-심층삼엽군" aria-label="Permalink to &quot;G27 심층삼엽군&quot;">​</a></h3><p>G27 심층삼엽군은 고대 해양 절지동물의 체형을 모방한 심층 검사 및 수문 유지보수 라인입니다. 납작한 다층 편평 장갑과 밀폐형 수중 추진 장치를 갖추어 고압 침수 구역과 오염수 하수관 내부를 자유롭게 이동합니다. 지하 수로 바닥에 붙어 관로 부식이나 이물질 막힘을 탐지하는 작업에 최적화되어 있습니다. S01 수문 갤러리와 S04 펌프 관로 수조 하부에 수평 배열로 봉인된 채 잠겨 있습니다.</p><p>재기동 개시점 서술 관로 유량 수위계가 사정권 이상으로 상승하거나 차단 밸브 신호가 유입될 때 재기동 시퀀스가 유발됩니다. 펌프 관로 바닥에서 일어난 심층삼엽군 기체들은 수중 음파 센서를 켜고 침수 통로 전체의 유기물 및 외부 이물질 제거 루틴을 개시합니다.</p><p>주요 장비 및 모듈 구성</p><ul><li>다층 편평 장갑: 높은 수압과 부식성 오염수로부터 내장 기판을 보호하는 적층형 외갑입니다.</li><li>밀폐형 수중 추진기: 수중 수류를 제어하며 관로 하상에 밀착해 이동할 수 있는 분사 장치입니다.</li><li>수중 초음파 센서: 탁도 높은 진흙 속에서도 관로 균열과 외부 물질을 식별합니다.</li><li>침전물 흡입 포트: 수로 바닥에 쌓인 요철과 이물질을 고압 흡입하여 분쇄 처리합니다.</li><li>유압 고정 앵커: 급류가 흐르는 하수관 내부에서 기체를 바닥에 견고히 고정합니다.</li></ul><h2 id="봉인·회수·쟁탈" tabindex="-1">봉인·회수·쟁탈 <a class="header-anchor" href="#봉인·회수·쟁탈" aria-label="Permalink to &quot;봉인·회수·쟁탈&quot;">​</a></h2><h3 id="로스트-테크-전환-원인" tabindex="-1">로스트 테크 전환 원인 <a class="header-anchor" href="#로스트-테크-전환-원인" aria-label="Permalink to &quot;로스트 테크 전환 원인&quot;">​</a></h3><p>도시의 자랑이었던 기계 라인들이 로스트 테크로 전락한 원인은 크게 세 가지로 요약됩니다.</p><ol><li><p>지시 서버 단절 도시 중앙 방재 제어반과의 유무선 통신이 완전히 끊기면서, 기체들은 상위 인가 명령이나 종료 신호를 받지 못하고 마지막 명령에 고착되었습니다.</p></li><li><p>도면 금고 S16 접근 상실 정밀 설계도와 제어 키가 보관된 S16 도면 금고 구역이 붕괴되어 물리적 접근이 차단되었습니다. 이로 인해 기체의 재제어 프로토콜을 복원하는 길이 막혔습니다.</p></li><li><p>기술 세대 격차 대붕괴 이후 생존한 지하 세력들은 붕괴 이전의 정밀 인공지능 제어 코드와 신경망 알고리즘을 해석할 학술적 자산을 잃었습니다. 기계는 해석 불가능한 고대 유물이 되었습니다.</p></li></ol><h3 id="지하-부품-경제" tabindex="-1">지하 부품 경제 <a class="header-anchor" href="#지하-부품-경제" aria-label="Permalink to &quot;지하 부품 경제&quot;">​</a></h3><p>로스트 기체는 위협적인 존재인 동시에 지하 사회에서 최고 가치를 지닌 기술 자원입니다. 기체 해체를 통해 확보할 수 있는 부품은 크게 세 가지로 분류됩니다.</p><ul><li>축전 모듈: 오랜 세월이 지나도 전하를 유지하는 고밀도 고체 축전지입니다. 거점 발전에 필수적입니다.</li><li>구동부 모듈: 유압 피스톤과 고부토크 모터로 이루어진 구동 장치입니다. 중장비 복구와 게이트 작동에 사용됩니다.</li><li>센서 모듈: 암시 시야와 진동 탐지 기능을 제공하는 복합 광학 센서 패널입니다. 경계 시설 구축에 거래됩니다.</li></ul><h3 id="회수-반과-가문의-경합" tabindex="-1">회수 반과 가문의 경합 <a class="header-anchor" href="#회수-반과-가문의-경합" aria-label="Permalink to &quot;회수 반과 가문의 경합&quot;">​</a></h3><p>봉인 갤러리와 정비고 구역은 주요 운영 가문들과 유물 회수 반의 핵심 쟁탈 대상입니다.</p><ul><li>HC22 테슬라코리아: 원형 기술의 완전한 독점을 노리고 봉인 구역 내부로 정밀 회수팀을 가장 먼저 침투시킵니다.</li><li>HC17 가문: 지하 보급로 안전 확보를 명분으로 주요 봉인 통로의 기체를 무력화하고 구획을 점거하려 합니다.</li><li>HP01 가문: 회수된 축전지와 센서 모듈을 지하 경매장에 공급하여 경제적 실리를 취하는 전략을 펼칩니다.</li></ul><p>무장 회수 반은 재기동 개시점을 먼저 점거하여 기체를 포획하거나, 즉시 무력화하여 핵심 모듈을 해체하는 방식으로 실적을 경쟁합니다.</p><h3 id="m040-몬스터-배치의-현장-적용" tabindex="-1">M040 몬스터 배치의 현장 적용 <a class="header-anchor" href="#m040-몬스터-배치의-현장-적용" aria-label="Permalink to &quot;M040 몬스터 배치의 현장 적용&quot;">​</a></h3><p>M040 배치에 포함된 로스트 기체 군집은 지정된 봉인 관로에서 개시점이 작동할 때 순차적으로 현장에 나타납니다.</p><ul><li>수색 전열: G25 등불개미군 기체들이 통로 선단에서 전력 진을 치고 침입자 반응을 검출합니다.</li><li>중장 거치대: G26 화석포효군 기체가 거점 교차로를 막아서서 중거리 접근을 물리적으로 차단합니다.</li><li>침수 기하망: G27 심층삼엽군이 수문 갤러리 하부 수로를 봉쇄하여 우화 및 탈출 경로를 막아섭니다.</li></ul><h3 id="협상-창-인터페이스-활용" tabindex="-1">협상 창 인터페이스 활용 <a class="header-anchor" href="#협상-창-인터페이스-활용" aria-label="Permalink to &quot;협상 창 인터페이스 활용&quot;">​</a></h3><p>탐사 대원은 현장에서 로스트 기체의 제어 단말이나 경쟁 가문 회수 반을 마주했을 때 협상 창 인터페이스를 적극 활용할 수 있습니다.</p><ul><li>프로토콜 카드 제출: 붕괴 이전 상위 인가 신호가 담긴 무선 카드를 사용해 기체의 전투 루틴을 일시 정지시킵니다.</li><li>부품 및 자원 교환: 정지된 기체의 교체용 부품이나 동력 셀을 제공하고 우회 통행 권한을 확보합니다.</li><li>가문 협상과 지분 분배: 회수 반과의 접촉 시 협상 창을 통해 유물 해체 지분을 나누거나 무력 충돌 없이 구역을 통과할 수 있습니다.</li><li>비상 중지 코드 입력: 단말에서 특정 해킹 퀴즈나 비밀번호를 타결하여 기체 그룹 전체를 정지 상태로 전환시킵니다.</li></ul><h2 id="실측과-창작-구분-표" tabindex="-1">실측과 창작 구분 표 <a class="header-anchor" href="#실측과-창작-구분-표" aria-label="Permalink to &quot;실측과 창작 구분 표&quot;">​</a></h2><table tabindex="0"><thead><tr><th>구분 항목</th><th>실측 개념 (Measured)</th><th>창작 레이어 (Fictional)</th></tr></thead><tbody><tr><td>설계 사상</td><td>생물모방(Biomimetics) 공학, 곤충 및 절지동물 구조</td><td>G25/G26/G27 독자 라인 명칭 및 세부 하부 모델</td></tr><tr><td>지형 적응</td><td>험지 다지 이동, 침수 수중 관로 검사 메커니즘</td><td>S01~S16 특정 봉인 갤러리 및 시험 트랙 좌표</td></tr><tr><td>제어 방식</td><td>분산 군집 제어, 센서 기반 자율 순찰 알고리즘</td><td>서버 단절로 인한 붕괴 이전 루틴의 영구 고착 서사</td></tr><tr><td>경제 요소</td><td>부품 재활용 및 고밀도 축전지 물리 특성</td><td>테슬라코리아·LG에너지솔루션·아리수수문가(HC22/HC17/HP01)의 유물 부품 회수 쟁탈 구도</td></tr><tr><td>재기동 트리거</td><td>외부 입력 전압 변동 및 센서 신호 유입 메커니즘</td><td>봉인 갤러리 차단막 개방 및 재기동 개시점 서사</td></tr><tr><td>인터페이스</td><td>기계 제어반 및 유무선 프로토콜 접속 표준</td><td>협상 창을 통한 발신 카드 제출 및 거래 교환 체계</td></tr><tr><td>배치 개체</td><td>수색, 중장 수리, 관로 유지보수 장비 카테고리</td><td>M040 몬스터 배치 군집 및 지정 격납 구획</td></tr></tbody></table><h2 id="연결" tabindex="-1">연결 <a class="header-anchor" href="#연결" aria-label="Permalink to &quot;연결&quot;">​</a></h2><ul><li><a href="/world/Hostile-Ecology-Index.html">적대 생태 총람</a></li><li><a href="/world/Monster-Batch-Manifest.html">몬스터 배치 원장</a></li><li><a href="/world/Operating-Houses.html">운영가문</a></li><li><a href="/world/Sixteen-States.html">서울 십육국</a></li></ul>',46)])])}const b=l(r,[["render",d]]);export{c as __pageData,b as default};
